test('boy council rise keeps the same patron and rival through promotion',()=>{const {run}=game();run(setup+'s.age=32;s.health=100;s.wealth=200;s.skill=100;s.prestige=90;s.experience.state=60;Object.keys(s.skills).forEach(k=>s.skills[k]=100);window.__pair=eventTargetSelections("statePair","bey_request")[0];window.__patron=__pair.target;window.__rival=__pair.other');for(const [id,ch] of [['bey_request',0],['council_pasture_case',0],['council_levy_choice',0],['council_rival_challenge',0],['council_support_test',0]])run(`window.__e=EVENT_DECK.find(x=>x.id==="${id}");window.__sel=eventTargetSelections(__e.target,__e.id)[0];if(__sel.target.id!==__patron.id||__sel.other.id!==__rival.id)throw Error("state pair drift");s.pendingEventId=__e.id;s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__sel.target.id,otherTargetId:__sel.other.id};chooseContextEvent(${ch})`);assert.equal(run('s.storyArcs.councilrise.nextEventId'),'council_bey_nomination');assert.equal(run('eventRequirementOK(EVENT_DECK.find(x=>x.id==="council_bey_nomination"))'),true);run('window.__e=EVENT_DECK.find(x=>x.id==="council_bey_nomination");window.__sel=eventTargetSelections(__e.target,__e.id)[0];s.pendingEventId=__e.id;s.pendingEventContext={age:s.age,year:s.year+s.age,month:2,targetId:__sel.target.id,otherTargetId:__sel.other.id};chooseContextEvent(0)');assert.equal(run('s.role'),'Boy Beyi');assert.equal(run('s.storyArcs.councilrise.status'),'completed');});
test('boy bey role is locked behind council influence and trust even when skills are high',()=>{const {run}=game();run(setup+'s.age=32;s.skill=100;s.prestige=90;s.experience.state=60;Object.keys(s.skills).forEach(k=>s.skills[k]=100);s.stateCourt={initialized:true,influence:0,councilTrust:30,tribeSupport:45,rivalPressure:30,obligations:0,decisions:[]}');assert.ok(run('careerIssue(D.careers.find(r=>r.id==="bey")).includes("nüfuzu")'));run('s.stateCourt.influence=25;s.stateCourt.councilTrust=20');assert.ok(run('careerIssue(D.careers.find(r=>r.id==="bey")).includes("güveni")'));run('s.stateCourt.councilTrust=40');assert.equal(run('careerIssue(D.careers.find(r=>r.id==="bey"))'),'');});
