test('battle wound creates serious ailment scar and a years-later flare',()=>{const {run}=game();run(setup+'s.age=30;s.military.served=true;s.military.active=true;s.health=100;s.pendingEventId="battle_wound";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1};chooseContextEvent(1)');assert.ok(run('s.ailments.some(x=>x.id==="deep_wound"&&x.severity===3)'));assert.ok(run('s.healthProfile.scars.some(x=>x.kind==="battle"&&x.severity===2)'));assert.ok(run('s.delayedEvents.some(x=>x.eventId==="old_wound_flare"&&x.status==="pending")'));assert.ok(run('physicalHealthIssue({kind:"training",id:"wrestling"}).length>0'));});
