test('rest and healer care shorten active ailments while healer care also reduces severity',()=>{const {run}=game();run(setup+'s.age=30;s.wealth=20;acquireAilment("deep_wound",{severity:3,duration:7,source:"test"});window.__before=s.ailments[0].remaining;healthAction("rest")');assert.ok(run('s.ailments[0].remaining<__before'));run('s.pendingEventId=null;s.pendingDecision=null;s.monthsRemaining=12;window.__sev=s.ailments[0].severity;healthAction("healer")');assert.ok(run('s.ailments.length===0||s.ailments[0].severity<__sev'));assert.ok(run('s.healthProfile.healerVisits>=1'));});
