test('a friend made in childhood is permanently marked as a childhood friend',()=>{const {run}=game();run(setup+'s.age=10;s.monthsRemaining=12;Math.random=()=>.5;addFriend()');assert.equal(run('s.friends.length'),1);assert.equal(run('ensureFriendProfile(s.friends[0]).childhood'),true);assert.ok(run('friendTier(s.friends[0]).includes("Çocukluk")'));});
test('deepening a friendship records shared experience and improves trust',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=12;window.__n=normalizeNPC({name:"Dost",gender:"male",age:20,alive:true,type:"Dost",rel:60,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];ensureSocialLife();window.__t=__n.bonds.trust;friendshipAction(0,"deepen")');assert.equal(run('s.monthsRemaining'),11);assert.ok(run('__n.bonds.trust>__t'));assert.ok(run('ensureFriendProfile(__n).sharedExperiences>=1'));});
test('a highly trusted friend can become an explicit confidant tier',()=>{const {run}=game();run(setup+'s.age=22;s.monthsRemaining=12;window.__n=normalizeNPC({name:"Sirdaş",gender:"female",age:21,alive:true,type:"Dost",rel:85,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=85;ensureSocialLife();friendshipAction(0,"confidant")');assert.equal(run('ensureFriendProfile(__n).chosenConfidant'),true);assert.equal(run('friendTier(__n)'),"Sırdaş");});
test('three strong friends form a circle and a gathering improves mutual NPC links',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;s.friends=[];for(let i=0;i<3;i++){let n=normalizeNPC({name:"F"+i,gender:i%2?"female":"male",age:24+i,alive:true,type:"Dost",rel:80,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");normalizeBonds(n);n.bonds.trust=75;s.friends.push(n)};ensureSocialLife();window.__g=autoCreateFriendCircle();window.__l=socialLinkBetween(s.friends[0],s.friends[1],true);window.__before=__l.score;friendCircleAction(__g.id,"gather")');assert.ok(run('__g&&__g.memberIds.length===3'));assert.ok(run('__l.score>__before'));assert.equal(run('__g.gatherings'),1);});
test('long distance and lack of contact can make a friend distant without deleting them',()=>{const {run}=game();run(setup+'s.age=25;window.__n=normalizeNPC({name:"Uzak",gender:"male",age:25,alive:true,type:"Dost",rel:70,realm:s.realm,place:"Uzak Yer",tribe:s.tribe},"Dost");s.friends=[__n];ensureSocialLife();for(let i=0;i<12;i++)tickFriendshipMonth({kind:"wait"})');assert.equal(run('ensureFriendProfile(__n).status'),"distant");assert.equal(run('s.friends.some(x=>x.id===__n.id)'),true);});
test('reconnecting with a distant loyal friend restores the active friendship',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;window.__n=normalizeNPC({name:"EskiDost",gender:"male",age:30,alive:true,type:"Dost",rel:80,realm:s.realm,place:s.place,tribe:s.tribe,traits:["sadik","sakin"]},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=80;window.__p=ensureFriendProfile(__n);__p.status="distant";__p.monthsDistant=36;Math.random=()=>0;friendshipAction(0,"reconnect")');assert.equal(run('__p.status'),"active");assert.equal(run('__p.monthsDistant'),0);assert.ok(run('s.socialLife.reconnections>=1'));});
test('a career friend referral creates a temporary career-entry bonus',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;window.__n=normalizeNPC({name:"DemirciDost",gender:"male",age:30,alive:true,type:"Dost",rel:80,role:"Demirci",realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=80;ensureSocialLife();friendshipAction(0,"referral");window.__r=D.careers.find(x=>x.id==="smith")');assert.ok(run('friendCareerReferralBonus(__r)>0'));assert.ok(run('s.socialLife.referrals.some(x=>x.friendId===__n.id&&x.path===__r.path)'));});
test('a trusted friend can introduce a partner candidate that remembers who introduced them',()=>{const {run}=game();run(setup+'s.age=24;s.monthsRemaining=12;s.partner=null;s.married=false;window.__n=normalizeNPC({name:"Araci",gender:"male",age:25,alive:true,type:"Dost",rel:80,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=80;ensureSocialLife();friendshipAction(0,"matchmake")');assert.ok(run('!!s.partner'));assert.equal(run('s.partner.statusFlags.introducedByFriend'),run('__n.id'));assert.ok(run('s.romance.current&&s.romance.current.partnerId===s.partner.id'));});
test('a military friend can become the same persistent NPC in the campaign-comrade pool',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;window.__n=normalizeNPC({name:"AlpDost",gender:"male",age:27,alive:true,type:"Dost",rel:80,role:"Alp",realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=80;ensureSocialLife();friendshipAction(0,"comrade")');assert.ok(run('s.military.comrades.some(x=>x.id===__n.id)'));assert.equal(run('s.military.comrades.find(x=>x.id===__n.id).id'),run('__n.id'));});
test('friend-circle conflict events directly change the same persistent group tension',()=>{const {run}=game();run(setup+'s.age=25;s.friends=[];for(let i=0;i<3;i++){let n=normalizeNPC({name:"G"+i,gender:"male",age:25+i,alive:true,type:"Dost",rel:80,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");normalizeBonds(n);n.bonds.trust=80;s.friends.push(n)};ensureSocialLife();window.__g=autoCreateFriendCircle();__g.tension=40;window.__n=s.friends[0];window.__before=__g.tension;applyFriendshipEvent("friend_circle_conflict",0,__n)');assert.ok(run('__g.tension<__before'));});
test('v18 saves migrate to v24 with social-life profiles and dedicated backup',()=>{const {run,storage}=game();run('s.version=18;delete s.socialLife;window.__n=normalizeNPC({name:"EskiDost",gender:"male",age:20,alive:true,type:"Dost",rel:70});s.friends=[__n];save();load()');assert.equal(run('s.version'),24);assert.ok(storage.has('yazgi_before_v24'));assert.ok(run('s.socialLife&&!!s.socialLife.profiles[s.friends[0].id]'));});
test('fresh lives carry an inactive persistent workplace profile',()=>{const {run}=game();assert.equal(run('s.version'),24);assert.ok(run('s.workplace&&Array.isArray(s.workplace.contacts)&&Array.isArray(s.workplace.history)'));assert.equal(run('s.workplace.roleId'),null);});
test('entering a career creates one supervisor and peer coworkers as persistent NPCs',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true)');assert.equal(run('s.workplace.roleId'),"smith");assert.equal(run('currentWorkplaceContacts().filter(x=>x.statusFlags.workplacePosition==="supervisor").length'),1);assert.ok(run('workplacePeers().length>=2'));assert.ok(run('currentWorkplaceContacts().every(x=>allNPCs().some(n=>n.id===x.id))'));});
test('collaborating with a coworker improves project progress standing and trust',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__n=workplacePeers()[0];window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);window.__p=s.workplace.projectProgress;window.__st=s.workplace.standing;window.__t=__n.bonds.trust;workplaceAction(__i,"collaborate")');assert.ok(run('s.workplace.projectProgress>__p'));assert.ok(run('s.workplace.standing>__st'));assert.ok(run('__n.bonds.trust>__t'));});
test('a trusted supervisor can sponsor the player for two years without bypassing career requirements',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__n=workplaceSupervisor();window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);__n.rel=95;__n.bonds.trust=95;__n.bonds.respect=95;s.workplace.standing=80;Math.random=()=>0;workplaceAction(__i,"sponsor")');assert.equal(run('s.workplace.sponsorId'),run('__n.id'));assert.ok(run('s.workplace.sponsorUntil>=s.year+s.age+2'));assert.ok(run('workplaceSponsorBonus()>0'));});
test('internal workplace promotion requires months standing mastery reputation and supervisor trust',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__w=s.workplace;window.__p=careerProfile("smith");window.__sup=workplaceSupervisor();__w.rank=0;__w.months=6;__w.standing=50;__w.conflict=0;__p.reputation=40;__p.mastery=40;__sup.bonds.trust=90;__sup.bonds.respect=90;window.__ok=workplacePromotionCheck()');assert.equal(run('__ok'),true);assert.equal(run('s.workplace.rank'),1);assert.ok(run('s.workplace.history.some(x=>x.type==="promotion")'));});
test('finishing a shared project records completion and rewards standing and prestige',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);s.workplace.projectProgress=96;s.prestige=50;window.__pr=s.prestige;tickWorkplaceMonth({kind:"work"})');assert.equal(run('s.workplace.projects'),1);assert.equal(run('s.workplace.projectProgress'),0);assert.ok(run('s.prestige>__pr'));});
test('peer competition can create a persistent workplace rival instead of a disposable event actor',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__n=workplacePeers()[0];window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);__n.bonds.grudge=34;Math.random=()=>0;workplaceAction(__i,"compete")');assert.ok(run('s.rivals.some(x=>x.id===__n.id)'));assert.ok(run('allNPCs().some(x=>x.id===__n.id)'));});
test('a workplace relationship can naturally turn the same coworker into a friend',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__n=workplacePeers()[0];window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);__n.rel=70;__n.bonds.trust=65;workplaceAction(__i,"befriend")');assert.ok(run('s.friends.some(x=>x.id===__n.id)'));assert.ok(run('!!s.socialLife.profiles[__n.id]'));});
test('senior workplace rank creates a junior and mentoring develops that same NPC',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);s.workplace.rank=2;workplaceYearTick();window.__n=workplaceJuniors()[0];window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);window.__respect=__n.bonds.respect;window.__skill=__n.skills[careerPrimarySkill(__r)]||0;s.monthsRemaining=12;workplaceAction(__i,"mentor")');assert.ok(run('!!__n'));assert.ok(run('__n.bonds.respect>__respect'));assert.ok(run('(__n.skills[careerPrimarySkill(__r)]||0)>__skill'));});
