test('age 50 plus family council is a real monthly action that improves family harmony and purpose',()=>{const {run}=game();run(setup+'s.age=60;s.monthsRemaining=12;s.children=[normalizeNPC({name:"Yetiskin",gender:"male",age:30,alive:true,rel:80,type:"Çocuk",realm:s.realm,place:s.place},"Çocuk")];ensureElderLife();window.__h=ensureSuccession().familyHarmony;window.__p=s.elderLife.purpose;elderAction("council")');assert.equal(run('s.monthsRemaining'),11);assert.ok(run('s.succession.familyHarmony>__h'));assert.ok(run('s.elderLife.purpose>__p'));assert.equal(run('s.elderLife.councils'),1);});

test('an elder can transfer their strongest skill to the same persistent younger NPC',()=>{const {run}=game();run(setup+'s.age=62;s.monthsRemaining=12;s.skills={riding:35,archery:44,combat:55,craft:92,literacy:60,speech:50,trade:40};window.__n=normalizeNPC({name:"Genc",gender:"female",age:22,alive:true,rel:75,type:"Çocuk",realm:s.realm,place:s.place,skills:{craft:10}},"Çocuk");s.children=[__n];ensureElderLife();window.__before=__n.skills.craft||0;elderAction("mentor",0)');assert.ok(run('__n.skills.craft>__before'));assert.ok(run('s.elderLife.mentorIds.includes(__n.id)'));assert.equal(run('s.elderLife.lessons'),1);});

test('a senior player can hand their active role to a persistent workplace junior and retire',()=>{const {run}=game();run(setup+'s.age=60;s.monthsRemaining=12;window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);s.workplace.rank=2;workplaceYearTick();window.__n=elderDelegateCandidates()[0];window.__id=__n.id;elderAction("delegate",0)');assert.equal(run('s.role'),null);assert.equal(run('s.retiredRole'),"Demirci");assert.equal(run('npcById(__id).role'),"Demirci");assert.equal(run('npcById(__id).statusFlags.succeededPlayer'),true);assert.equal(run('s.elderLife.delegations'),1);assert.ok(run('s.workplace.formerCircles.length>0'));});

test('age 60 plus can move into a trusted adult child household and gain care support',()=>{const {run}=game();run(setup+'s.age=65;s.monthsRemaining=12;window.__n=normalizeNPC({name:"Evlat",gender:"male",age:35,alive:true,rel:90,type:"Çocuk",realm:s.realm,place:s.place},"Çocuk");normalizeBonds(__n);__n.bonds.trust=90;s.children=[__n];ensureElderLife();window.__care=s.elderLife.careSupport;elderAction("childhome",0)');assert.equal(run('s.housing.mode'),"hosted_yurt");assert.equal(run('s.housing.hostId'),run('__n.id'));assert.ok(run('s.elderLife.careSupport>__care'));assert.equal(run('s.elderLife.hostChildId'),run('__n.id'));});

test('v22 elder events update the persistent elder-life profile through the decision engine',()=>{const {run}=game();run(setup+'s.age=65;s.children=[normalizeNPC({name:"Evlat",gender:"female",age:30,alive:true,rel:80,type:"Çocuk",realm:s.realm,place:s.place},"Çocuk")];window.__n=s.children[0];ensureElderLife();window.__p=s.elderLife.purpose;s.pendingEventId="elder_child_advice_v21";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__n.id};chooseContextEvent(0)');assert.ok(run('s.elderLife.purpose>__p'));assert.ok(run('__n.bonds.trust>0'));assert.ok(run('s.elderLife.history.some(x=>x.type==="event")'));});

