test('an autonomous NPC illness blocks ordinary interaction and exposes care actions',()=>{const {run}=game();run(setup+'s.age=30;window.__n=s.parents[0];npcWorldTrigger(__n,"illness",{years:2,severity:2});window.__idx=0;window.__issue=accessIssue({kind:"npc",group:"parents",index:0,id:"spend"});window.__html=npcLifeActionsHtml(__n)');assert.ok(run('__issue.includes("hasta")'));assert.ok(run('__html.includes("Başında kal")'));assert.ok(run('__html.includes("Otacı getir")'));assert.equal(run('eventTargetCandidates("parent").some(x=>x.id===__n.id)'),true);assert.equal(run('eventTargetSelections("parent").some(x=>x.target.id===__n.id)'),false);});

test('captive relatives cannot be treated like normal NPCs and ransom support can return the same NPC',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;window.__n=s.siblings[0]||normalizeNPC({name:"Kardes",gender:"male",age:25,alive:true,type:"Erkek kardeş",rel:75,realm:s.realm,place:s.place},"Erkek kardeş");if(!s.siblings.some(x=>x.id===__n.id))s.siblings.push(__n);window.__home=__n.place;npcWorldTrigger(__n,"captivity",{years:3});window.__issue=accessIssue({kind:"npc",group:"siblings",index:s.siblings.findIndex(x=>x.id===__n.id),id:"spend"});npcLifeAction(__n.id,"ransom");s.pendingEventId=null;s.pendingDecision=null;s.monthsRemaining=12;npcLifeAction(__n.id,"ransom")');assert.ok(run('__issue.includes("tutsak")'));assert.equal(run('__n.lifeState.status'),"normal");assert.equal(run('__n.place'),run('__home'));assert.ok(run('__n.lifeState.history.some(x=>x.type==="captivity")'));assert.ok(run('__n.lifeState.history.some(x=>x.type==="return")'));});

test('exiled NPCs live elsewhere and player mediation can bring the exact same person home',()=>{const {run}=game();run(setup+'s.age=35;s.monthsRemaining=12;s.skills.speech=100;s.prestige=100;window.__n=s.parents[0];window.__home=__n.place;window.__places=D.realms[__n.realm].places.filter(x=>x!==__home);npcWorldTrigger(__n,"exile",{years:4,place:__places[0]});window.__away=__n.place;for(let i=0;i<3&&__n.lifeState.status==="exiled";i++){s.pendingEventId=null;s.pendingDecision=null;s.monthsRemaining=12;npcLifeAction(__n.id,"appeal")}');assert.ok(run('__away!==__home'));assert.equal(run('__n.lifeState.status'),"normal");assert.equal(run('__n.place'),run('__home'));assert.ok(run('s.npcWorld.counts.exile>=1'));});

test('autonomous migration changes NPC location without deleting relationship or identity',()=>{const {run}=game();run(setup+'s.age=30;window.__n=s.friends[0]||normalizeNPC({name:"Dost",gender:"male",age:30,alive:true,type:"Dost",rel:75,realm:s.realm,place:s.place},"Dost");if(!s.friends.some(x=>x.id===__n.id))s.friends.push(__n);window.__id=__n.id;window.__old=__n.place;window.__dest=D.realms[__n.realm].places.find(x=>x!==__old);npcWorldTrigger(__n,"migration",{place:__dest})');assert.equal(run('__n.id'),run('__id'));assert.ok(run('__n.place!==__old'));assert.ok(run('s.friends.some(x=>x.id===__id)'));assert.ok(run('__n.lifeState.history.some(x=>x.type==="migration")'));});

test('family year tick progresses and resolves active NPC life states instead of freezing them forever',()=>{const {run}=game();run(setup+'s.age=40;window.__n=s.parents[0];npcWorldTrigger(__n,"illness",{years:1,severity:1});__n.health=90;Math.random=()=>0;window.__year=s.year+s.age;familyTick()');assert.equal(run('__n.lifeState.status'),"normal");assert.ok(run('s.npcWorld.counts.recovery>=1'));});

test('v21 saves migrate to v24 with living-world state and dedicated backup',()=>{const {run,storage}=game();run('s.version=21;delete s.npcWorld;for(const n of allNPCs())delete n.lifeState;save();load()');assert.equal(run('s.version'),24);assert.ok(storage.has('yazgi_before_v24'));assert.ok(run('s.npcWorld&&Array.isArray(s.npcWorld.history)'));assert.ok(run('allNPCs().every(n=>n.lifeState&&Array.isArray(n.lifeState.history))'));});


test('fresh lives initialize persistent v24 adult-child family branches',()=>{const {run}=game();assert.equal(run('s.version'),24);assert.ok(run('s.familyBranches&&s.familyBranches.children&&s.familyBranches.assetHeirs&&s.familyBranches.stewards&&Array.isArray(s.familyBranches.childInLaws)'));});

test('supporting an adult child spends a month and strengthens their independent household',()=>{const {run}=game();run(setup+'s.age=50;s.wealth=40;s.monthsRemaining=12;window.__c=normalizeNPC({name:"Yetiskin",gender:"male",age:25,alive:true,type:"Çocuk",rel:80,goal:"family",realm:s.realm,place:s.place},"Çocuk");s.children=[__c];ensureParenting();ensureFamilyBranches();window.__w=s.wealth;adultChildAction(__c.id,"support")');assert.equal(run('s.monthsRemaining'),11);assert.equal(run('__w-s.wealth'),4);assert.ok(run('ensureAdultChildProfile(__c).householdSupport>=10'));assert.ok(run('__c.wealth>=4'));});

test('adult child can be introduced to an existing persistent NPC without replacing identity',()=>{const {run}=game();run(setup+'s.age=50;s.monthsRemaining=12;window.__c=normalizeNPC({name:"Ogul",gender:"male",age:25,alive:true,type:"Çocuk",rel:90,goal:"family",realm:s.realm,place:s.place,traits:["sadik","caliskan"]},"Çocuk");s.children=[__c];window.__n=normalizeNPC({name:"Tanidik",gender:"female",age:24,alive:true,type:"Dost",rel:90,realm:s.realm,place:s.place,traits:["sadik","merhametli"]},"Dost");normalizeBonds(__n);__n.bonds.trust=95;s.friends=[__n];ensureFamilyBranches();Math.random=()=>0;adultChildAction(__c.id,"match",__n.id)');assert.equal(run('__c.partner.id'),run('__n.id'));assert.equal(run('__n.statusFlags.familyMatchedTo'),run('__c.id'));assert.ok(run('s.familyBranches.childInLaws.some(x=>x.id===__n.id&&x.statusFlags.childInLawFor===__c.id)'));assert.equal(run('s.familyBranches.introductions'),1);});

test('adult child may reject a family-arranged introduction when their own choice wins',()=>{const {run}=game();run(setup+'s.age=50;s.monthsRemaining=12;window.__c=normalizeNPC({name:"Kiz",gender:"female",age:24,alive:true,type:"Çocuk",rel:60,goal:"peace",realm:s.realm,place:s.place,traits:["hirsli","gururlu"]},"Çocuk");s.children=[__c];window.__n=normalizeNPC({name:"Aday",gender:"male",age:25,alive:true,type:"Dost",rel:45,realm:s.realm,place:s.place},"Dost");normalizeBonds(__n);__n.bonds.trust=35;s.friends=[__n];ensureFamilyBranches();ensureAdultChildProfile(__c).autonomy=100;ensureAdultChildProfile(__c).familyReadiness=10;Math.random=()=>.99;adultChildAction(__c.id,"match",__n.id)');assert.ok(run('!__c.partner'));assert.ok(run('ensureAdultChildProfile(__c).autonomy>=100'));assert.equal(run('s.familyBranches.introductions'),0);});

test('family career connection can open a real role for an adult child',()=>{const {run}=game();run(setup+'s.age=50;s.monthsRemaining=12;s.prestige=90;window.__c=normalizeNPC({name:"Cocuk",gender:"female",age:24,alive:true,type:"Çocuk",rel:90,goal:"mastery",realm:s.realm,place:s.place,skills:{craft:70}},"Çocuk");s.children=[__c];window.__m=normalizeNPC({name:"Usta",gender:"male",age:48,alive:true,type:"Demirci Ustası",role:"Demirci",rel:85,realm:s.realm,place:s.place,statusFlags:{careerKind:"smith"}},"Demirci Ustası");s.careerContacts=[__m];ensureFamilyBranches();Math.random=()=>0;adultChildAction(__c.id,"career")');assert.equal(run('__c.role'),"Demirci");assert.equal(run('s.familyBranches.careerOpenings'),1);assert.ok(run('ensureAdultChildProfile(__c).careerMomentum>40'));});

test('family-plan conversation boosts future grandchild chance but does not create a child instantly',()=>{const {run}=game();run(setup+'s.age=50;s.monthsRemaining=12;window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:26,alive:true,type:"Çocuk",rel:90,goal:"family",realm:s.realm,place:s.place,traits:["sadik","caliskan"]},"Çocuk");__c.partner=normalizeNPC({name:"Es",gender:"female",age:25,alive:true,type:"Eş",rel:80,realm:s.realm,place:s.place},"Eş");s.children=[__c];ensureFamilyBranches();window.__before=__c.descendants.length;window.__chance0=familyBranchBirthChance(__c);Math.random=()=>0;adultChildAction(__c.id,"family");window.__chance1=familyBranchBirthChance(__c)');assert.equal(run('__c.descendants.length'),run('__before'));assert.ok(run('ensureAdultChildProfile(__c).familyPlanUntil>=s.year+s.age+2'));assert.ok(run('__chance1>__chance0'));});

test('productive family asset can be assigned to an adult child and a named asset can be separately bequeathed',()=>{const {run}=game();run(setup+'s.age=55;s.monthsRemaining=12;s.assets=["smithy","yurt"];ensureEconomy();window.__a=normalizeNPC({name:"A",gender:"male",age:28,alive:true,type:"Çocuk",rel:85,realm:s.realm,place:s.place},"Çocuk");window.__b=normalizeNPC({name:"B",gender:"female",age:25,alive:true,type:"Çocuk",rel:85,realm:s.realm,place:s.place},"Çocuk");s.children=[__a,__b];ensureFamilyBranches();adultChildAction(__a.id,"enterprise","smithy");s.pendingEventId=null;s.pendingDecision=null;s.monthsRemaining=12;adultChildAction(__b.id,"bequeath","yurt");window.__sa=inheritanceShareFor(__a,[__a,__b]);window.__sb=inheritanceShareFor(__b,[__a,__b])');assert.equal(run('s.familyBranches.stewards.smithy'),run('__a.id'));assert.equal(run('s.familyBranches.assetHeirs.yurt'),run('__b.id'));assert.ok(run('__sa.assets.includes("smithy")'));assert.ok(run('__sb.assets.includes("yurt")'));assert.ok(run('!__sa.assets.includes("yurt")'));});

test('grandparent can spend time with and teach a persistent grandchild',()=>{const {run}=game();run(setup+'s.age=55;s.monthsRemaining=12;Object.keys(s.skills).forEach(k=>s.skills[k]=90);window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:30,alive:true,type:"Çocuk",rel:85,realm:s.realm,place:s.place},"Çocuk");window.__g=normalizeNPC({name:"Torun",gender:"female",age:8,alive:true,type:"Çocuk",rel:65,realm:s.realm,place:s.place,parentIds:[__c.id],skills:{}},"Çocuk");__c.descendants=[__g];__c.children=1;s.children=[__c];ensureFamilyBranches();window.__rel=__g.rel;grandchildAction(__g.id,"spend");s.pendingEventId=null;s.pendingDecision=null;s.monthsRemaining=12;window.__skill=Math.max(0,...Object.values(__g.skills));grandchildAction(__g.id,"teach")');assert.ok(run('__g.rel>__rel'));assert.ok(run('Math.max(0,...Object.values(__g.skills))>__skill'));assert.equal(run('s.familyBranches.grandparentActions'),2);});

test('child spouse living-world state is synchronized and blocks family planning while unavailable',()=>{const {run}=game();run(setup+'s.age=50;window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:25,alive:true,type:"Çocuk",rel:90,realm:s.realm,place:s.place},"Çocuk");s.children=[__c];window.__n=normalizeNPC({name:"Tanidik",gender:"female",age:24,alive:true,type:"Dost",rel:90,realm:s.realm,place:s.place},"Dost");normalizeBonds(__n);__n.bonds.trust=95;s.friends=[__n];ensureFamilyBranches();Math.random=()=>0;s.monthsRemaining=12;adultChildAction(__c.id,"match",__n.id);s.pendingEventId=null;s.pendingDecision=null;npcWorldTrigger(__n,"illness",{years:2,severity:2});syncAdultChildPartner(__c)');assert.equal(run('__c.partner.lifeState.status'),"ill");assert.ok(run('npcLifeBlocksNormalInteraction(__c.partner)'));assert.ok(run('familyBranchBirthChance(__c)>0'));});

test('v23 family event changes the persistent adult-child profile through the context engine',()=>{const {run}=game();run(setup+'s.age=50;window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:25,alive:true,type:"Çocuk",rel:80,realm:s.realm,place:s.place},"Çocuk");s.children=[__c];ensureFamilyBranches();window.__a=ensureAdultChildProfile(__c).autonomy;s.pendingEventId="adult_child_own_path_v23";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"wait",targetId:__c.id};chooseContextEvent(0)');assert.ok(run('ensureAdultChildProfile(__c).autonomy>__a'));assert.equal(run('s.pendingEventId'),null);assert.ok(run('ensureAdultChildProfile(__c).history.some(x=>x.type==="event")'));});

test('v22 saves migrate to v24 with family branches and a dedicated backup',()=>{const {run,storage}=game();run('s.version=22;delete s.familyBranches;save();load()');assert.equal(run('s.version'),24);assert.ok(storage.has('yazgi_before_v24'));assert.ok(run('s.familyBranches&&s.familyBranches.children&&s.familyBranches.assetHeirs&&s.familyBranches.stewards'));});


test('v24 stable loyal marriage does not qualify for a betrayal event',()=>{const {run}=game();run(setup+'s.age=35;window.__p=normalizeNPC({name:"Es",gender:"female",age:33,alive:true,type:"Eş",rel:90,realm:s.realm,place:s.place,traits:["sadik","merhametli"]},"Eş");s.partner=__p;s.married=true;ensureRomance();s.romance.current.harmony=90;s.romance.current.commitment=92;s.romance.current.tension=4;s.romance.current.neglectMonths=0;s.romance.current.compatibility=88;window.__risk=marriageBetrayalRisk();window.__ev=EVENT_DECK.find(e=>e.id==="marriage_betrayal_v24")');assert.ok(run('__risk<30'));assert.equal(run('eventRequirementOK(__ev)'),false);});

test('v24 betrayal risk is driven by tension neglect commitment and compatibility',()=>{const {run}=game();run(setup+'s.age=35;window.__p=normalizeNPC({name:"Es",gender:"female",age:33,alive:true,type:"Eş",rel:65,realm:s.realm,place:s.place,traits:["hirsli","kinci"]},"Eş");s.partner=__p;s.married=true;ensureRomance();s.romance.current.harmony=28;s.romance.current.commitment=30;s.romance.current.tension=85;s.romance.current.neglectMonths=9;s.romance.current.compatibility=35;window.__risk=marriageBetrayalRisk();window.__ev=EVENT_DECK.find(e=>e.id==="marriage_betrayal_v24")');assert.ok(run('__risk>=58'));assert.equal(run('eventRequirementOK(__ev)'),true);});

test('confronting betrayal creates a persistent third party and evidence instead of random flavor text',()=>{const {run}=game();run(setup+'s.age=35;window.__p=normalizeNPC({name:"Es",gender:"female",age:33,alive:true,type:"Eş",rel:65,realm:s.realm,place:s.place,traits:["hirsli","kinci"]},"Eş");s.partner=__p;s.married=true;ensureRomance();s.romance.current.tension=90;s.romance.current.commitment=25;s.romance.current.harmony=25;s.romance.current.neglectMonths=10;s.pendingEventId="marriage_betrayal_v24";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"wait",targetId:__p.id};chooseContextEvent(0);window.__third=romanceThirdParty()');assert.ok(run('s.romance.current.betrayal.discovered'));assert.ok(run('s.romance.current.betrayal.unresolved'));assert.ok(run('s.romance.current.betrayal.evidence>=70'));assert.ok(run('__third&&__third.statusFlags.romanceThirdParty'));assert.ok(run('s.romance.contacts.some(x=>x.id===__third.id)'));});

test('betrayal settlement gives the betraying spouse a smaller wealth share than amicable separation',()=>{const {run}=game();run(setup+'s.age=40;s.wealth=100;window.__p=normalizeNPC({name:"Es",gender:"female",age:38,alive:true,type:"Eş",rel:70,realm:s.realm,place:s.place,wealth:20},"Eş");s.partner=__p;s.married=true;ensureRomance();s.romance.current.monthsTogether=120;s.romance.current.sharedWork=8;s.romance.current.householdContribution=80;recordPartnerBetrayal(80);window.__a=marriageSettlement("amicable");window.__b=marriageSettlement("betrayal")');assert.ok(run('__b.rate<__a.rate'));assert.ok(run('__b.wealth<__a.wealth'));});

test('betrayal separation archives the ex, records settlement and places shared minor children in a real household arrangement',()=>{const {run}=game();run(setup+'s.age=38;s.wealth=100;s.monthsRemaining=12;window.__p=normalizeNPC({name:"Es",gender:"female",age:36,alive:true,type:"Eş",rel:70,realm:s.realm,place:s.place,wealth:15},"Eş");s.partner=__p;s.married=true;ensureRomance();s.romance.current.monthsTogether=96;window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:9,alive:true,type:"Çocuk",rel:80,realm:s.realm,place:s.place,parentIds:[s.id,__p.id]},"Çocuk");s.children=[__c];recordPartnerBetrayal(80);window.__id=__p.id;window.__w=s.wealth;separationAction("betrayal");window.__rec=s.romance.separations[0]');assert.equal(run('s.married'),false);assert.equal(run('s.partner'),null);assert.ok(run('s.exPartners.some(x=>x.id===__id)'));assert.equal(run('__rec.mode'),"betrayal");assert.ok(run('__w>s.wealth'));assert.equal(run('__c.statusFlags.separationId'),run('__rec.id'));assert.equal(run('__c.statusFlags.primaryHousehold'),"player");assert.ok(run('s.delayedEvents.some(x=>x.id==="separation_child_adjustment_v24"&&x.targetId===__c.id)'));});

test('tore separation can place children with the other household and create annual care contribution',()=>{const {run}=game();run(setup+'s.age=38;s.wealth=20;s.monthsRemaining=12;window.__p=normalizeNPC({name:"Es",gender:"female",age:36,alive:true,type:"Eş",rel:75,realm:s.realm,place:s.place,wealth:100},"Eş");s.partner=__p;s.married=true;ensureRomance();s.romance.current.monthsTogether=84;window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:8,alive:true,type:"Çocuk",rel:80,realm:s.realm,place:s.place,parentIds:[s.id,__p.id]},"Çocuk");s.children=[__c];separationAction("tore");window.__rec=s.romance.separations[0];window.__after=s.wealth;s.age++;separationYearTick()');assert.equal(run('__rec.residence'),"former_partner");assert.ok(run('__rec.careContribution>=1'));assert.ok(run('s.wealth<__after'));assert.equal(run('__c.statusFlags.primaryHousehold'),"former_partner");});

test('named child inheritance protects that asset from marriage settlement transfer',()=>{const {run}=game();run(setup+'s.age=45;s.wealth=100;window.__p=normalizeNPC({name:"Es",gender:"female",age:42,alive:true,type:"Eş",rel:75,realm:s.realm,place:s.place},"Eş");s.partner=__p;s.married=true;ensureRomance();s.romance.current.monthsTogether=180;s.romance.current.sharedWork=20;s.assets=["flock","smithy","bow"];ensureEconomy();window.__c=normalizeNPC({name:"Varis",gender:"male",age:20,alive:true,type:"Çocuk",rel:85,realm:s.realm,place:s.place},"Çocuk");s.children=[__c];ensureFamilyBranches();s.familyBranches.assetHeirs.flock=__c.id;window.__set=marriageSettlement("amicable")');assert.ok(run('__set.asset!=="flock"'));});

test('forgiving a discovered betrayal keeps the marriage but clears unresolved crisis with a lasting record',()=>{const {run}=game();run(setup+'s.age=35;window.__p=normalizeNPC({name:"Es",gender:"female",age:33,alive:true,type:"Eş",rel:70,realm:s.realm,place:s.place},"Eş");s.partner=__p;s.married=true;ensureRomance();recordPartnerBetrayal(60);applyMarriageCrisisEffect({mode:"forgive"});window.__b=s.romance.current.betrayal');assert.equal(run('s.married'),true);assert.equal(run('__b.unresolved'),false);assert.ok(run('__b.forgiven>=1'));assert.ok(run('__b.incidents>=1'));});

test('v24 separation summary exposes localized child arrangement instead of internal state names',()=>{const {run}=game();run(setup+'s.age=38;s.wealth=30;s.monthsRemaining=12;window.__p=normalizeNPC({name:"Es",gender:"female",age:36,alive:true,type:"Eş",rel:75,realm:s.realm,place:s.place,wealth:100},"Eş");s.partner=__p;s.married=true;ensureRomance();window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:8,alive:true,type:"Çocuk",rel:80,realm:s.realm,place:s.place,parentIds:[s.id,__p.id]},"Çocuk");s.children=[__c];separationAction("tore");window.__html=marriageCrisisSummaryHtml()');assert.ok(run('__html.includes("diğer ebeveynin ocağı")'));assert.ok(run('!__html.includes("former_partner")'));});

test('v23 saves migrate to v24 with betrayal and separation containers plus dedicated backup',()=>{const {run,storage}=game();run('s.version=23;s.romance={history:[],totalRelationships:0};save();load()');assert.equal(run('s.version'),24);assert.ok(storage.has('yazgi_before_v24'));assert.ok(run('Array.isArray(s.romance.contacts)&&Array.isArray(s.romance.separations)'));});
